import{_ as o,c as a,o as e,ag as l}from"./chunks/framework._xRlcm3f.js";const m=JSON.parse('{"title":"Halo 网页版配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/custom-haloweb.md","filePath":"platforms/custom-haloweb.md","lastUpdated":1790228279000}'),r={name:"platforms/custom-haloweb.md"};function d(i,t,s,n,h,c){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="halo-网页版配置指南" tabindex="-1">Halo 网页版配置指南 <a class="header-anchor" href="#halo-网页版配置指南" aria-label="Permalink to &quot;Halo 网页版配置指南&quot;">​</a></h1><p>通过 <strong>Cookie 授权</strong>发布到 <strong>Halo 2.20+</strong>。图片默认走「当前平台」（Halo 附件库）。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个 Halo 2.20+ 站点（含后台登录账号）。</li><li>在浏览器登录 Halo 后台。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>Halo 博客首页完整地址，如 <code>https://yourhalo.com</code></td></tr><tr><td>API 地址</td><td>通常和首页地址相同</td></tr><tr><td>Cookie</td><td>点「1 去登录」登录后关闭窗口，再点「2 自动读取 Cookie」；也可展开「手动编辑」直接粘贴</td></tr><tr><td>预览规则</td><td>查看文章链接模板，默认 <code>/archives/{slug}</code></td></tr><tr><td>发布格式</td><td>默认 HTML</td></tr><tr><td>图床</td><td>默认「当前平台」（Halo 附件库）；不需要上传图片时可选「不使用」</td></tr></tbody></table><blockquote><p>⚠️ 必须先填「平台首页」完整 URL，再点登录/读取 Cookie；否则会提示 <code>Invalid URL</code>。</p></blockquote><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「1 去登录」→ 自动打开 Halo 登录页 → 用后台账号登录 → <strong>关闭窗口</strong>（关闭时保存 Cookie）。</li><li>点「2 自动读取 Cookie」→ 验证 → 账号状态「运行中」。</li><li>快速发布 → 选 Halo网页版 → 发布。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>提示「Invalid URL」</strong>：先填完整站点地址，再点登录/读取 Cookie。</li><li><strong>Halo 版本要求</strong>：需 2.20 及以上。</li><li><strong>验证报「接口返回异常/登录状态可能已失效」</strong>：Cookie 过期或 Halo 重启导致会话失效，重新登录读取 Cookie。</li><li><strong>图片图床</strong>：默认「当前平台」即可；需要与思源一致的图床时可改选 PicGo。</li></ul>',11)])])}const b=o(r,[["render",d]]);export{m as __pageData,b as default};
